//@ run-pass
// Clifford Algebra Cl(1,3) — Spacetime Type System Validation
//
// Validates core algebraic properties that the Hyper<Clifford(p,q)> type
// checker must enforce:
//   - Cl(1,3) geometric product is ASSOCIATIVE (unlike octonions)
//   - Cl(1,3) geometric product is NOT commutative
//   - Cl(1,3) HAS zero divisors (requires Div effect)
//   - Cl(1,3) is NOT a division algebra (inverse not always defined)
//   - Cayley-Dickson tower properties are distinct from Clifford properties
//
// Future: these properties will be checked at compile time via
//   is_associative(Clifford(1,3)) == true
//   has_zero_divisors(Clifford(1,3)) == true
//   is_division_algebra(Clifford(1,3)) == false

fn abs_f64(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn approx_eq(a: f64, b: f64, tol: f64) -> bool {
    abs_f64(a - b) < tol
}

// Precomputed sign table for Cl(1,3): 16x16 = 256 entries
var cl13_table: [f64; 256] = [0.0; 256]
var cl13_ready: bool = false

fn geo_sign(a: i64, b: i64) -> f64 with Mut, Panic, Div {
    var swaps = 0
    var j = 0
    while j < 4 {
        if (b >> j) & 1 != 0 {
            var k = j + 1
            while k < 4 {
                if (a >> k) & 1 != 0 { swaps = swaps + 1 }
                k = k + 1
            }
        }
        j = j + 1
    }
    let common = a & b
    var msign = 1.0
    if (common >> 1) & 1 != 0 { msign = 0.0 - msign }
    if (common >> 2) & 1 != 0 { msign = 0.0 - msign }
    if (common >> 3) & 1 != 0 { msign = 0.0 - msign }
    if swaps % 2 == 0 { return msign }
    return 0.0 - msign
}

fn init_cl13_table() with Mut, Panic, Div {
    if cl13_ready { return }
    var i = 0
    while i < 16 {
        var j = 0
        while j < 16 {
            cl13_table[i * 16 + j] = geo_sign(i, j)
            j = j + 1
        }
        i = i + 1
    }
    cl13_ready = true
}

fn geo_sign_fast(a: i64, b: i64) -> f64 with Panic {
    return cl13_table[a * 16 + b]
}

fn geo_product(a: [f64], b: [f64]) -> [f64] with Mut, Panic, Div {
    init_cl13_table()
    var r0  = 0.0; var r1  = 0.0; var r2  = 0.0; var r3  = 0.0
    var r4  = 0.0; var r5  = 0.0; var r6  = 0.0; var r7  = 0.0
    var r8  = 0.0; var r9  = 0.0; var r10 = 0.0; var r11 = 0.0
    var r12 = 0.0; var r13 = 0.0; var r14 = 0.0; var r15 = 0.0
    var i = 0
    while i < 16 {
        if a[i] != 0.0 {
            var j = 0
            while j < 16 {
                if b[j] != 0.0 {
                    let k = i ^ j
                    let val = geo_sign_fast(i, j) * a[i] * b[j]
                    if k == 0 { r0 = r0 + val }
                    else if k == 1 { r1 = r1 + val }
                    else if k == 2 { r2 = r2 + val }
                    else if k == 3 { r3 = r3 + val }
                    else if k == 4 { r4 = r4 + val }
                    else if k == 5 { r5 = r5 + val }
                    else if k == 6 { r6 = r6 + val }
                    else if k == 7 { r7 = r7 + val }
                    else if k == 8 { r8 = r8 + val }
                    else if k == 9 { r9 = r9 + val }
                    else if k == 10 { r10 = r10 + val }
                    else if k == 11 { r11 = r11 + val }
                    else if k == 12 { r12 = r12 + val }
                    else if k == 13 { r13 = r13 + val }
                    else if k == 14 { r14 = r14 + val }
                    else if k == 15 { r15 = r15 + val }
                }
                j = j + 1
            }
        }
        i = i + 1
    }
    return [r0, r1, r2, r3, r4, r5, r6, r7,
            r8, r9, r10, r11, r12, r13, r14, r15]
}

fn mv_basis(idx: i64) -> [f64] with Mut, Panic, Div {
    var r0  = 0.0; var r1  = 0.0; var r2  = 0.0; var r3  = 0.0
    var r4  = 0.0; var r5  = 0.0; var r6  = 0.0; var r7  = 0.0
