//@ run-pass
//@ expect-stdout: MADAROS_GUM_MULTICHANNEL_FO_PASS

// Madaros multi-channel FO GUM (lean_single β¹⁰/β¹¹ parity target):
//   Var(y) = Σ_k (∂y/∂x_k)² · σ²_k
//
// Closes residuals that scalar-variance algebra cannot:
//   R2 p1−p2 cancel for separately-bound identical products
//   R3 (a*b)*a partial correlation → a²b form
//   R7 ac−bc shared-factor correlation
//   R8 a*(a*b) right-assoc partial correlation

fn abs_f(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn main() with IO, Mut, Div, Epistemic {
    let a: Knowledge<f64> = measure(2.0, uncertainty: 0.05)
    let b: Knowledge<f64> = measure(3.0, uncertainty: 0.05)
    let c: Knowledge<f64> = measure(4.0, uncertainty: 0.05)
    let av = a.value
    let bv = b.value
    let cv = c.value

    // R1 independent product
    let v_ab = variance_of(av * bv)
    // R2 p1−p2 cancel
    let p1 = av * bv
    let p2 = av * bv
    let v_pp = variance_of(p1 - p2)
    // R3 partial correlation (a*b)*a = a²b
    // truth: 4 a² b² Va + a⁴ Vb = 0.40
    let v_aba = variance_of((av * bv) * av)
    let v_aab = variance_of((av * av) * bv)
    // R4 three-way independent
    let v_abc = variance_of((av * bv) * cv)
    // R5 (a+b)*c
    let v_sumprod = variance_of((av + bv) * cv)
    // R7 ac − bc = (a−b)c
    // truth: c²Va + c²Vb + (a−b)²Vc = 0.0825
    let q1 = av * cv
    let q2 = bv * cv
    let v_qdiff = variance_of(q1 - q2)
    // R8 a*(a*b)
    let v_xxy = variance_of(av * (av * bv))

    print("R1="); print_f64(v_ab); print("\n")
    print("R2="); print_f64(v_pp); print("\n")
    print("R3_aba="); print_f64(v_aba); print("\n")
    print("R3_aab="); print_f64(v_aab); print("\n")
    print("R4="); print_f64(v_abc); print("\n")
    print("R5="); print_f64(v_sumprod); print("\n")
    print("R7="); print_f64(v_qdiff); print("\n")
    print("R8="); print_f64(v_xxy); print("\n")

    let ok = abs_f(v_ab - 0.0325) < 1.0e-9
        && abs_f(v_pp) < 1.0e-9
        && abs_f(v_aba - 0.40) < 1.0e-9
        && abs_f(v_aab - 0.40) < 1.0e-9
        && abs_f(v_abc - 0.61) < 1.0e-9
        && abs_f(v_sumprod - 0.1425) < 1.0e-9
        && abs_f(v_qdiff - 0.0825) < 1.0e-9
        && abs_f(v_xxy - 0.40) < 1.0e-9
    if ok {
        print("MADAROS_GUM_MULTICHANNEL_FO_PASS\n")
    } else {
        print("MADAROS_GUM_MULTICHANNEL_FO_FAIL\n")
    }
}

//@ run-pass
//@ requires: madaros
//@ expect-stdout: LOWERCASE_STRUCT_GENERIC_ASSOC_CALL PASS
//
// PR #2515 review round 2, finding B (comment_id 4089110697): the
// specializer's `spec_call_expr_callee_name` (self-hosted/check/specializer.sio)
// used to treat a multi-segment turbofish path's capitalization alone as
// module evidence -- an uppercase-first-byte root meant "Type::method,
// leave alone", a lowercase root meant "must be a module-qualified free-fn
// call, rewrite to the bare terminal symbol". That is unsound: a
// lowercase-named struct is legal Sounio (see
// tests/multimodule/private_fn_identity/reserved/pfi_res_b.sio's
// `struct helper_`), so a lowercase-rooted `Type::assoc_fn::<T>(..)` path
// could be misread as a qualified free-fn call and have its whole path
// collapsed by spec_rewrite_call_mut to the bare monomorphized `assoc_fn`
// symbol -- silently accepting an invalid/misresolved namespace.
//
// `wrap_` here is a lowercase-named generic struct with a generic
// associated (not instance) function, called through its path with an
// explicit turbofish (`wrap_::make::<i64>(..)`) -- the exact shape the
// unsound heuristic could misfire on, since `wrap_` is never `use`d as a
// module anywhere (there is nothing to `use`; this is single-file). The
// fixed specializer only rewrites a multi-segment turbofish path to a bare
// free-fn call when the qualifier resolves against real `use` data
// (spec_path_qualifier_all_modules_known); since `wrap_` is not a
// `use`-declared module, this path is left alone for ordinary
// Type::method / associated-call resolution instead.
struct wrap_<T> {
    v: T,
}

impl wrap_<T> {
    fn make(v: T) -> wrap_<T> with Mut, Panic {
        wrap_ { v: v }
    }
}

fn main() -> i32 with IO, Mut, Panic {
    let w = wrap_::make::<i64>(42)
    if w.v == 42 {
        println("LOWERCASE_STRUCT_GENERIC_ASSOC_CALL PASS")
        return 0
    }
    println("LOWERCASE_STRUCT_GENERIC_ASSOC_CALL FAIL")
    1
}

