//@ run-pass
//@ description: Tiny pseudo-Boolean forced-literal propagation checker smoke

fn pb_bool_valid(x: i64) -> i64 {
    if x == 0 { return 1 }
    if x == 1 { return 1 }
    if x == (0 - 1) { return 1 }
    return 0
}

fn pb_min_term(w: i64, x: i64) -> i64 {
    if x == 1 { return w }
    return 0
}

fn pb_max_term(w: i64, x: i64) -> i64 {
    if x == 0 { return 0 }
    return w
}

fn pb_min_sum3(w0: i64, x0: i64, w1: i64, x1: i64, w2: i64, x2: i64) -> i64 {
    return pb_min_term(w0, x0) + pb_min_term(w1, x1) + pb_min_term(w2, x2)
}

fn pb_max_sum3(w0: i64, x0: i64, w1: i64, x1: i64, w2: i64, x2: i64) -> i64 {
    return pb_max_term(w0, x0) + pb_max_term(w1, x1) + pb_max_term(w2, x2)
}

fn pb_valid_slot3(slot: i64) -> i64 {
    if slot == 0 { return 1 }
    if slot == 1 { return 1 }
    if slot == 2 { return 1 }
    return 0
}

fn pb_slot_unknown3(x0: i64, x1: i64, x2: i64, slot: i64) -> i64 {
    if pb_valid_slot3(slot) == 0 { return 0 }
    if slot == 0 { if x0 == (0 - 1) { return 1 } }
    if slot == 1 { if x1 == (0 - 1) { return 1 } }
    if slot == 2 { if x2 == (0 - 1) { return 1 } }
    return 0
}

fn pb_weight_at3(w0: i64, w1: i64, w2: i64, slot: i64) -> i64 {
    if slot == 0 { return w0 }
    if slot == 1 { return w1 }
    if slot == 2 { return w2 }
    return 0 - 1
}

fn pb_check_le_forces_false3(w0: i64, x0: i64, w1: i64, x1: i64, w2: i64, x2: i64, rhs: i64, slot: i64) -> i64 {
    if w0 < 0 { return 0 }
    if w1 < 0 { return 0 }
    if w2 < 0 { return 0 }
    if pb_bool_valid(x0) == 0 { return 0 }
    if pb_bool_valid(x1) == 0 { return 0 }
    if pb_bool_valid(x2) == 0 { return 0 }
    if pb_slot_unknown3(x0, x1, x2, slot) == 0 { return 0 }
    if pb_min_sum3(w0, x0, w1, x1, w2, x2) + pb_weight_at3(w0, w1, w2, slot) > rhs { return 1 }
    return 0
}

fn pb_check_ge_forces_true3(w0: i64, x0: i64, w1: i64, x1: i64, w2: i64, x2: i64, rhs: i64, slot: i64) -> i64 {
    if w0 < 0 { return 0 }
    if w1 < 0 { return 0 }
    if w2 < 0 { return 0 }
    if pb_bool_valid(x0) == 0 { return 0 }
    if pb_bool_valid(x1) == 0 { return 0 }
    if pb_bool_valid(x2) == 0 { return 0 }
    if pb_slot_unknown3(x0, x1, x2, slot) == 0 { return 0 }
    if pb_max_sum3(w0, x0, w1, x1, w2, x2) - pb_weight_at3(w0, w1, w2, slot) < rhs { return 1 }
    return 0
}

fn main() -> i64 {
    // 2*x0 + 3*x1 + 5*x2 <= 6, with x0=true and x2 unknown:
    // setting x2=true gives 7 > 6, so x2 is forced false.
    if pb_check_le_forces_false3(2, 1, 3, 0 - 1, 5, 0 - 1, 6, 2) != 1 { return 1 }
    if pb_check_le_forces_false3(2, 1, 3, 0 - 1, 5, 0 - 1, 7, 2) != 0 { return 2 }
    if pb_check_le_forces_false3(2, 1, 3, 0 - 1, 5, 0, 6, 2) != 0 { return 3 }
    if pb_check_le_forces_false3(2, 1, 0 - 3, 0 - 1, 5, 0 - 1, 6, 2) != 0 { return 4 }
    if pb_check_le_forces_false3(2, 1, 3, 2, 5, 0 - 1, 6, 2) != 0 { return 5 }
    if pb_check_le_forces_false3(2, 1, 3, 0 - 1, 5, 0 - 1, 6, 4) != 0 { return 6 }

    // 2*x0 + 3*x1 + 5*x2 >= 7, with x0=false and x2 unknown:
    // setting x2=false leaves max 3 < 7, so x2 is forced true.
    if pb_check_ge_forces_true3(2, 0, 3, 0 - 1, 5, 0 - 1, 7, 2) != 1 { return 7 }
    if pb_check_ge_forces_true3(2, 0, 3, 0 - 1, 5, 0 - 1, 3, 2) != 0 { return 8 }
    if pb_check_ge_forces_true3(2, 0, 3, 0 - 1, 5, 1, 7, 2) != 0 { return 9 }
    if pb_check_ge_forces_true3(2, 0, 3, 0 - 1, 0 - 5, 0 - 1, 7, 2) != 0 { return 10 }
    if pb_check_ge_forces_true3(2, 0, 3, 4, 5, 0 - 1, 7, 2) != 0 { return 11 }
    if pb_check_ge_forces_true3(2, 0, 3, 0 - 1, 5, 0 - 1, 7, 4) != 0 { return 12 }

    return 0
}

//@ run-pass
//@ timeout: 240
// Focused M5 validation: cumulants, inverse-AUC derivatives, and PBPK28
// fourth-order budget emission.
//
// Timeout: `souc run` takes 26 s under lean_single on the workspace (the
// 7-parameter Hessian and M5 budgets at dt = 0.1 h over 168 h); the CI
// runner measures 2.65-4.3x slower (c0fffb987), so up to ~112 s. 240 s is
// ~2x that. The 30 s default would time it out.

use darwin_pbpk::cumulants::*

fn t_abs(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn rel_err(a: f64, b: f64) -> f64 with Div {
    let d = t_abs(a - b)
    let den = if t_abs(b) > 1.0e-12 { t_abs(b) } else { 1.0 }
    d / den
}

fn check_close(tag: string, got: f64, expected: f64, tol: f64) -> bool with IO, Div {
    let r = rel_err(got, expected)
    print(tag); print(" got="); print_f64(got)
    print(" expected="); print_f64(expected)
    print(" rel_err="); print_f64(r); println("")
    return r <= tol
}

fn gaussian_fixture_cumulant() -> CumulantSummary with Mut, Div {
    // Three-point Gaussian-moment fixture: P(0)=2/3, P(+/-sqrt(3))=1/6.
    // The first four central moments are mean=0, variance=1, kappa3=0,
    // kappa4=0, so it is a deterministic check of the Pébay update.
    var s = cumulant_init()
    s = cumulant_update(s, 0.0 - 1.7320508075688772)
    s = cumulant_update(s, 1.7320508075688772)
    s = cumulant_update(s, 0.0)
    s = cumulant_update(s, 0.0)
    s = cumulant_update(s, 0.0)
    s = cumulant_update(s, 0.0)
    cumulant_finalize(s)
}

fn main() -> i32 with IO, Mut, Div, Panic, Epistemic {
    var failed = 0

    println("======================================================================")
    println("  M5 PBPK28 GUM Fourth-Order Cumulant Budget")
    println("======================================================================")

    let g = gaussian_fixture_cumulant()
    print("Gaussian fixture kappa3: "); print_f64(g.kappa3); println("")
    print("Gaussian fixture kappa4: "); print_f64(g.kappa4); println("")
    if t_abs(g.kappa3) < 1.0e-9 && t_abs(g.kappa4) < 1.0e-9 {
        println("Gaussian cumulant fixture: PASS")
    } else {
        println("Gaussian cumulant fixture: FAIL")
        failed = failed + 1
    }

    let lc = lognormal_cumulants_from_mean_variance(12.4, 22.202944)
    print("Lognormal CL sigma2_log: "); print_f64(lc.sigma2_log); println("")
    print("Lognormal CL kappa3:     "); print_f64(lc.kappa3); println("")
    print("Lognormal CL kappa4:     "); print_f64(lc.kappa4); println("")
    if lc.kappa3 > 0.0 && lc.kappa4 > 0.0 && lc.central4 > 0.0 {
        println("Lognormal cumulants positive: PASS")
    } else {
        println("Lognormal cumulants positive: FAIL")
        failed = failed + 1
    }

    let dose = 5.0
    let cl = 12.4
    let v = 1.0
    let h = 0.001
    let der_inv = extract_auc_inverse_derivatives(dose, cl, v, h)
    let d1_expected = 0.0 - dose / (cl * cl * v)
    let d2_expected = 2.0 * dose / (cl * cl * cl * v)
    let d3_expected = 0.0 - 6.0 * dose / (cl * cl * cl * cl * v)
    if !check_close("dAUC/dCL", der_inv.d1[0], d1_expected, 1.0e-6) { failed = failed + 1 }
    if !check_close("d2AUC/dCL2", der_inv.d2[0], d2_expected, 1.0e-4) { failed = failed + 1 }
    if !check_close("d3AUC/dCL3", der_inv.d3[0], d3_expected, 1.0e-3) { failed = failed + 1 }

    println("")
    println("Running PBPK28 M6 fourth-order convergence budget ...")
    let bud = m5_pbpk28_convergence_budget()
    print("u_MC canonical:          "); print_f64(m5_pbpk28_u_mc_canonical()); println("")
    print("u_1st direct:            "); print_f64(bud.u_1st); println("")
    print("u_2nd full Hessian:      "); print_f64(bud.u_2nd_hessian); println("")
    print("u_total fourth-order:    "); print_f64(bud.u_total); println("")
    print("rel_hess_residual:       "); print_f64(bud.rel_hess_residual); println("")
    print("rel_fourth_residual:     "); print_f64(bud.rel_fourth_residual); println("")
    print("dominant_correction_idx: "); print_f64(bud.dominant_index as f64); println("")
    print("var_1st:                 "); print_f64(bud.var_1st); println("")
    print("var_skewness:            "); print_f64(bud.var_skewness); println("")
    print("var_kurtosis:            "); print_f64(bud.var_kurtosis); println("")
    print("var_cubic:               "); print_f64(bud.var_cubic); println("")
    print("var_total:               "); print_f64(bud.var_total); println("")

    if !bud.success || bud.u_1st <= 0.0 {
        println("PBPK28 budget failed")
        failed = failed + 1
    }
    var claim_failed = 0
    if bud.rel_fourth_residual < bud.rel_hess_residual {
        println("Fourth-order improves over full second-order Hessian: PASS")
    } else {
        println("Fourth-order improves over full second-order Hessian: FAIL")
        claim_failed = 1
    }

    // The assertion above is the M5 scientific claim. On the corrected
    // (clamp-free) kernel it no longer holds (rel_fourth 0.258 > rel_hess
    // 0.019; docs/audit/PBPK28_CN_RANNACHER_MASS_BALANCE_2026-09-26.md), so
    // this test reports that through its exit code instead of printing PASS.
    // It is not flipped to pin the new outcome: re-deciding the claim belongs
    // to the M5 regeneration dispatch.
    // The known-failure manifest pins _OUTPUT, so it must mean "only the M5
    // claim failed". Any other failed check (fixtures, derivatives, budget)
    // prints _FAIL instead, which the pin does not match: a regression there
    // is reported as a fresh fail, not absorbed by the known claim failure.
    if failed > 0 {
        println("M5_GUM_FOURTH_ORDER_CUMULANT_BUDGET_FAIL")
        return (failed + claim_failed) as i32
