    let k_alpha: Knowledge<f64> = measure( 1.0, uncertainty: 0.01)  // a.e3
    let k_beta:  Knowledge<f64> = measure( 1.0, uncertainty: 0.01)  // a.e10
    let k_gamma: Knowledge<f64> = measure( 1.0, uncertainty: 0.01)  // b.e6
    let k_delta: Knowledge<f64> = measure(-1.0, uncertainty: 0.01)  // b.e15

    let alpha = k_alpha.value
    let beta  = k_beta.value
    let gamma = k_gamma.value
    let delta = k_delta.value

    print("Uncertain coefficients (sigma = 0.01 each):\n")
    print("  alpha (a.e3)  = "); println(alpha)
    print("  beta  (a.e10) = "); println(beta)
    print("  gamma (b.e6)  = "); println(gamma)
    print("  delta (b.e15) = "); println(delta)
    print("\n")

